            let x = get(sorted, j).unwrap()
            let y = get(sorted, j + 1).unwrap()
            if x > y {
                let temp = y
                sorted = push(sorted, temp)
                sorted = push(sorted, x)
                sorted = pop(sorted)
                sorted = pop(sorted)
            }
        }
    }
    sorted
}

