fn exchange(v: Vec<Int>) -> Vec<Int> {
    let len = len(v)
    if len > 1 {
        let first = get(v, 0)
        let last = get(v, len - 1)
        let mut new_v = push(vec(), last)
        for i in 1 {
            let x = get(v, i)
            new_v = push(new_v, x)
        }
        new_v = push(new_v, first)
        new_v
    } else {
        v
    }
}

