    self.into_iter().filter_map(move || f).collect()
}

fn into_iter(self: Vec<Str>) -> VecIterator<Str> {
    VecIterator(self)
}

fn map(self: VecIterator<Str>, f: Fn<Str>) -> VecIterator<Str> {
    VecIterator(self.into_iter().map(move || f))
}

struct VecIterator {
    iter: VecIteratorImpl,
}

struct VecIteratorImpl {
    index: Int,
    values: Vec<Str>,
}

fn next(self: VecIterator) -> Option<Str> {
    let next = self.iter.next()
    if next.is_some() {
        Some(next.unwrap())
    } else {
        None
    }
}

fn len(self: VecIterator) -> Int {
    self.iter.len()
}

fn enumerate(self: VecIterator) -> VecIterator<Str> {
    VecIterator(self.iter.enumerate().map(move || Tuple(_, _)))
}

fn filter_map(self: VecIterator, f: Fn<Str>) -> VecIterator<Str> {
    VecIterator(self.into_iter().filter_map(move || f))
}

fn into_iter(self: VecIterator) -> VecIteratorImpl {
    VecIteratorImpl(self.iter.into_iter())
}

fn map(self: VecIteratorImpl, f: Fn<Str>) -> VecIteratorImpl {
    VecIteratorImpl(self.index, self.values.map(move || f))
}

fn next(self: VecIteratorImpl) -> Option<Str> {
    if self.index < self.values.len() {
        let next = self.values.get(self.index)
        self.index = self.index + 1
        next
    } else {
        None
    }
